"""Lexique : définitions courtes, autonomes, avec leur source officielle. Les mots sont ceux des artisans et des propriétaires ; le jargon des plateformes est cité dans la définition."""
SRC = {'cnil': ('CNIL, prospection par téléphone', 'https://www.cnil.fr/fr/prospection-commerciale-par-telephone-hors-automate-dappel-quelles-sont-les-regles'), 'l223': ('Code de la consommation, L223-1 et suivants', 'https://www.legifrance.gouv.fr/codes/section_lc/LEGITEXT000006069565/LEGISCTA000032221441/2026-08-11'), 'devis': ('Service-Public, devis obligatoire', 'https://www.service-public.fr/particuliers/vosdroits/F31144'), 'decennale': ('Service-Public, garantie décennale', 'https://www.service-public.fr/particuliers/vosdroits/F2034'), 'dp': ('Service-Public, déclaration préalable', 'https://www.service-public.fr/particuliers/vosdroits/F17578'), 'retract': ('DGCCRF, contrats conclus hors établissement', 'https://www.economie.gouv.fr/dgccrf/les-fiches-pratiques/faq-contrats-conclus-hors-etablissement-et-demarchage-domicile'), 'rge': ('Ministère de la Transition écologique, label RGE', 'https://www.ecologie.gouv.fr/politiques-publiques/label-reconnu-garant-lenvironnement-rge'), 'rge_annu': ("annuaire France Rénov'", 'https://france-renov.gouv.fr/annuaires-professionnels/artisan-rge-architecte'), 'siren': ('Annuaire des entreprises', 'https://annuaire-entreprises.data.gouv.fr/')}
CLIENTS = [('demande-de-devis', 'Demande de devis', "Une demande de devis est le message laissé par un particulier qui envisage des travaux : nom, téléphone, commune et projet. Les plateformes parlent de « lead » ou de « contact ». Ce n'est pas encore un client : il faut le rappeler, vérifier le projet, puis fixer une visite.", [], []), ('demande-partagee', 'Demande partagée', 'Une demande partagée est une demande de devis vendue à plusieurs entreprises en même temps, le « lead partagé » des plateformes. Le propriétaire reçoit plusieurs appels, et le choix se fait souvent sur la rapidité du rappel ou sur le prix.', [('/blog/lead-partage-lead-exclusif-rendez-vous-qualifie/', 'demande partagée, demande exclusive, rendez-vous qualifié')], []), ('demande-exclusive', 'Demande exclusive', "Une demande exclusive est une demande de devis transmise à une seule entreprise, le « lead exclusif » des plateformes. Elle n'est proposée à aucun concurrent, mais l'artisan doit encore rappeler le propriétaire et vérifier son projet lui-même.", [('/blog/lead-partage-lead-exclusif-rendez-vous-qualifie/', 'demande partagée, demande exclusive, rendez-vous qualifié')], []), ('rendez-vous-qualifie', 'Rendez-vous qualifié', "Un rendez-vous qualifié est une visite déjà fixée chez un propriétaire dont le projet a été vérifié au téléphone : il est propriétaire, il sait quels travaux il veut, sa commune est dans la zone de l'artisan et son délai est clair.", [('/#process', 'notre méthode')], []), ('plateforme-de-devis', 'Plateforme de devis', 'Une plateforme de devis est un site qui recueille des demandes de travaux et les propose à des artisans, contre un abonnement ou un prix par contact. Selon la plateforme, une même demande peut être envoyée à plusieurs entreprises.', [], []), ('apporteur-d-affaires', "Apporteur d'affaires", "Un apporteur d'affaires met un artisan en relation avec des clients et touche une commission sur les chantiers signés. Le montant de la commission et ses conditions doivent être écrits dans un contrat.", [], []), ('exclusivite-de-secteur', 'Exclusivité de secteur', "L'exclusivité de secteur réserve une zone à un seul artisan d'un métier : les demandes de cette zone ne sont proposées à aucun concurrent. Chez Bartier & Co, c'est un artisan par métier et par secteur.", [('/metiers/', 'les métiers')], []), ('rayon-d-intervention', "Rayon d'intervention", "Le rayon d'intervention est la distance autour du dépôt dans laquelle un artisan accepte des chantiers. Pour des annonces locales, il se règle commune par commune, souvent entre 25 et 40 km.", [('/meta-ads/', 'annonces Facebook et Instagram')], []), ('annonces-locales', 'Annonces locales', "Les annonces locales sont des publicités montrées seulement aux habitants d'une zone. Sur Google, elles apparaissent quand quelqu'un cherche un artisan ; sur Facebook et Instagram, elles touchent les propriétaires du secteur avant qu'ils ne cherchent.", [('/google-ads/', 'Google Ads'), ('/meta-ads/', 'Meta Ads')], []), ('taux-de-signature', 'Taux de signature des devis', 'Le taux de signature, aussi appelé taux de transformation, est la part des devis envoyés qui sont signés. Il se calcule ainsi : devis signés ÷ devis envoyés × 100. Par exemple, 6 devis signés sur 20 envoyés donnent 30 %.', [('/blog/relance-devis-artisan/', 'relance de devis')], []), ('cout-par-chantier-signe', 'Coût par chantier signé', "Le coût par chantier signé additionne toutes les dépenses engagées pour trouver des clients sur une période (publicité, abonnements, commissions) et les divise par le nombre de chantiers signés. C'est le bon chiffre pour comparer deux canaux.", [('/blog/google-ads-ou-meta-ads-artisan/', 'Google Ads ou Meta Ads')], []), ('relance-de-devis', 'Relance de devis', "La relance de devis consiste à recontacter le propriétaire après l'envoi du devis pour savoir où il en est. Un appel quelques jours après l'envoi, puis un SMS, suffisent souvent. Après trois tentatives sans réponse, mieux vaut arrêter.", [('/blog/relance-devis-artisan/', 'relance de devis : calendrier, SMS et script')], []), ('demarchage-telephonique', 'Démarchage téléphonique (règle de 2026)', "Depuis le 11 août 2026, un professionnel ne peut plus appeler un particulier pour lui proposer un bien ou un service sans son accord préalable, sauf contrat en cours. Rappeler un particulier qui a lui-même demandé à être contacté reste possible, s'il en garde la preuve.", [], ['cnil', 'l223'])]
TRAVAUX = [('devis', 'Devis', "Un devis est la proposition écrite et détaillée d'un artisan : travaux, matériaux, prix et délais. Une fois accepté, il engage l'artisan au prix indiqué. Pour un dépannage, une réparation ou un entretien à domicile, le devis est obligatoire avant toute intervention.", [], ['devis']), ('reception-des-travaux', 'Réception des travaux', 'La réception est le moment où le propriétaire accepte les travaux, avec ou sans réserves, en général par un procès-verbal signé. Elle fait partir les garanties de 1, 2 et 10 ans.', [], []), ('garantie-de-parfait-achevement', 'Garantie de parfait achèvement', "Pendant 1 an après la réception, l'artisan doit réparer tous les défauts signalés, qu'ils aient été notés à la réception ou qu'ils soient apparus ensuite. Elle est prévue par l'article 1792-6 du Code civil.", [], []), ('garantie-biennale', 'Garantie biennale', "Pendant 2 ans après la réception, l'artisan doit réparer ou remplacer les équipements qui ne fonctionnent pas et qui se démontent sans abîmer le bâtiment, comme des volets roulants. Elle est prévue par l'article 1792-3 du Code civil.", [], []), ('garantie-decennale', 'Garantie décennale', "La garantie décennale oblige l'artisan à réparer, pendant 10 ans après la réception, les dommages qui menacent la solidité du bâtiment ou le rendent impropre à son usage. L'assurance qui la couvre est obligatoire, et son nom doit figurer sur le devis.", [], ['decennale']), ('delai-de-retractation', 'Délai de rétractation', "Un contrat de travaux signé chez vous, hors du local de l'artisan, peut être annulé sans motif pendant 14 jours. Aucun paiement n'est dû avant 7 jours. Ces règles ne s'appliquent pas à une réparation urgente que vous avez vous-même demandée.", [], ['retract']), ('declaration-prealable', 'Déclaration préalable de travaux', "La déclaration préalable est l'autorisation à demander en mairie avant des travaux qui changent l'aspect extérieur d'une maison : matériau ou couleur de la toiture, façade, fenêtres. Des travaux à l'identique n'en demandent en général pas, sauf en secteur protégé.", [('/devis-travaux/', 'devis de travaux')], ['dp']), ('rge', "RGE (reconnu garant de l'environnement)", "RGE est une mention accordée aux entreprises du bâtiment engagées dans une démarche de qualité en rénovation énergétique. Elle est obligatoire pour que des travaux ouvrent droit à MaPrimeRénov'. Vérifiez qu'elle couvre le type de travaux prévu.", [('/devis-travaux/isolation/', 'devis isolation')], ['rge', 'rge_annu']), ('siren', 'SIREN', "Le SIREN est le numéro à 9 chiffres qui identifie une entreprise en France. Il se vérifie gratuitement sur l'Annuaire des entreprises de l'État : une entreprise introuvable ou radiée doit vous alerter.", [('/devis-travaux/', 'reconnaître un artisan sérieux')], ['siren'])]
